solutions.naive:
class Solution:
    def subarraySum(self, nums: list[int], k: int) -> int:
        ans = 0
        for l in range(len(nums)):
            for r in range(l, len(nums)):
                total = 0
                for i in range(l, r + 1):
                    total += nums[i]
                if total == k:
                    ans += 1
        return ans

