class Solution:
    def subarraySum(self, nums: list[int], k: int) -> int:
        counts = {0: 1}
        total = ans = 0
        for x in nums:
            total += x
            ans += counts.get(total - k, 0)
            counts[total] = counts.get(total, 0) + 1
        return ans

